{"explanation":"The graph of y = tan(x) repeats every π and has vertical asymptotes wherever cos(x) = 0, because tan(x) = sin(x)/cos(x). From −2π to 2π, these occur at x = −3π/2, −π/2, π/2, and 3π/2. As x approaches any asymptote, tan(x) tends to +∞ from the left and −∞ from the right; the function is undefined on the asymptote itself.","manimCode":"const pi = Math.PI;
const ax = new Axes({ xRange: [-2*pi, 2*pi, pi/2], yRange: [-3.3, 3.3, 1], xLength: 11.4, yLength: 4.6, tips: false });
const title = new Text({ text: 'y = tan(x)', fontSize: 34, color: BLUE });
title.moveTo([0, 3.22, 0]);
const formula = new MathTex({ latex: 'x = \\frac{\\pi}{2} + k\\pi \\quad (k \\in \\mathbb{Z})', color: RED });
await formula.waitForRender();
formula.scale(0.65);
formula.moveTo([0, 2.72, 0]);
scene.add(title, formula, ax);

// Plot each branch separately: never connect across a discontinuity.
const visibleAngle = Math.atan(3.3);
const curves = [];
for (let k = -2; k <= 2; k++) {
  const lo = Math.max(-2*pi, k*pi - visibleAngle);
  const hi = Math.min(2*pi, k*pi + visibleAngle);
  const branch = ax.plot(x => Math.tan(x), { xRange: [lo, hi, 0.015], color: BLUE });
  branch.setStrokeWidth(3);
  curves.push(branch);
}
const asymptotes = [];
const asymValues = [-1.5*pi, -0.5*pi, 0.5*pi, 1.5*pi];
const asymNames = ['-\\frac{3\\pi}{2}', '-\\frac{\\pi}{2}', '\\frac{\\pi}{2}', '\\frac{3\\pi}{2}'];
for (let i = 0; i < asymValues.length; i++) {
  const xx = asymValues[i];
  const dashed = new DashedLine({ start: ax.c2p(xx, -3.3), end: ax.c2p(xx, 3.3), color: RED });
  dashed.setOpacity(0.7);
  asymptotes.push(dashed);
  const label = new MathTex({ latex: asymNames[i], color: RED });
  await label.waitForRender();
  label.scale(0.55);
  label.moveTo([ax.c2p(xx, 0)[0], -2.57, 0]);
  scene.add(label);
}
for (const sign of [-1, 1]) {
  const endpointLabel = new MathTex({ latex: sign < 0 ? '-2\\pi' : '2\\pi', color: GRAY });
  await endpointLabel.waitForRender();
  endpointLabel.scale(0.55);
  endpointLabel.moveTo([ax.c2p(sign*2*pi, 0)[0], -0.35, 0]);
  scene.add(endpointLabel);
}
await scene.play(new AnimationGroup([...asymptotes.map(m => new Create(m)), ...curves.map(m => new Create(m))]));

let selectedX = pi/4;
const handle = new Dot({ point: ax.c2p(selectedX, Math.tan(selectedX)), radius: 0.13, color: YELLOW });
const guide = new DashedLine({ start: ax.c2p(selectedX, 0), end: ax.c2p(selectedX, Math.tan(selectedX)), color: YELLOW });
guide.setOpacity(0.5);
const readout = new Text({ text: '', fontSize: 24, color: YELLOW });
readout.moveTo([0, -3.03, 0]);
const hint = new Text({ text: 'Drag the yellow point across branches • red dashed lines are not part of the graph', fontSize: 18, color: GRAY });
hint.moveTo([0, -3.48, 0]);
scene.add(guide, handle, readout, hint);

function update() {
  const yy = Math.tan(selectedX);
  handle.moveTo(ax.c2p(selectedX, yy));
  guide.setStart(ax.c2p(selectedX, 0));
  guide.setEnd(ax.c2p(selectedX, yy));
  readout.setText('x = ' + (selectedX/pi).toFixed(3) + 'π     tan(x) = ' + yy.toFixed(3));
}
update();
makeDraggable(handle, scene, { onDrag: (mob, pos) => {
  const requested = Math.max(-2*pi, Math.min(2*pi, ax.pointToCoords(pos)[0]));
  const branchIndex = Math.max(-2, Math.min(2, Math.round(requested/pi)));
  const lo = Math.max(-2*pi, branchIndex*pi - visibleAngle);
  const hi = Math.min(2*pi, branchIndex*pi + visibleAngle);
  selectedX = Math.max(lo, Math.min(hi, requested));
  update();
} });
await scene.wait(999999);"}

